import{_ as r,a0 as a,w as i,s,ao as d,I as e,x as o,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"OpenBoard：面向教育工作者的开源交互式白板 | LCTT x X-CMD","titleTemplate":false,"description":"OpenBoard：面向教育工作者的开源交互式白板 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OpenBoard：面向教育工作者的开源交互式白板 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OpenBoard：面向教育工作者的开源交互式白板 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220118 OpenBoard- An Open Source Interactive Whiteboard for Educators","title":"OpenBoard：面向教育工作者的开源交互式白板","tag":"202201","desc":""},"relativePath":"202201/20220118 OpenBoard- An Open Source Interactive Whiteboard for Educators.md","filePath":"[post].md"}'),u={name:"202201/20220118 OpenBoard- An Open Source Interactive Whiteboard for Educators.md"};function m(f,t,b,O,B,x){const l=a("Link");return i(),s("div",null,[t[21]||(t[21]=d('<h1 id="openboard-面向教育工作者的开源交互式白板" tabindex="-1">OpenBoard：面向教育工作者的开源交互式白板 <a class="header-anchor" href="#openboard-面向教育工作者的开源交互式白板" aria-label="Permalink to “OpenBoard：面向教育工作者的开源交互式白板”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202201/25/134634wzn22l0x3zycy9et.jpg" alt=""></p><blockquote><p>OpenBoard 是为中小学和大学定制的交互式开源白板。让我们来看看它提供了什么。</p></blockquote><p>有几个可用于教育的开源工具，但是，并非所有这些面向中小学和大学的软件都能达到商业软件级的良好维护。</p><p>OpenBoard 就是这样一个不同凡响的自由开源工具，它可以不打折扣地为教育服务。它是一个交互式白板程序，具有所有基本功能，并支持各种硬件。</p><h3 id="openboard-自由及开源的交互式白板" tabindex="-1">OpenBoard：自由及开源的交互式白板 <a class="header-anchor" href="#openboard-自由及开源的交互式白板" aria-label="Permalink to “OpenBoard：自由及开源的交互式白板”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/openboard-screenshot.png?resize=800%2C435&amp;ssl=1" alt=""></p><p>作为一个自由开源的程序，OpenBoard 看起来是一个令人印象深刻的选择。</p><p>瑞士日内瓦州的教育部门（DIP）与 GitHub 上的社区一起维护该工具。</p><p>通过交互式白板促进简单的数字教学不应该花费很多，这就是 OpenBoard 的优势所在。</p><p>它提供的一系列功能对大多数中小学和大学来说应该是足够的。</p><p>虽然我无法在中小学/大学环境中测试它，但我会重点介绍它提供的主要功能。</p><h3 id="openboard-的特点" tabindex="-1">OpenBoard 的特点 <a class="header-anchor" href="#openboard-的特点" aria-label="Permalink to “OpenBoard 的特点”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/openboard-screenshot-1.png?resize=800%2C462&amp;ssl=1" alt=""></p><p>交互式白板没有众多花哨的功能，但足以使教师能够尽可能轻松地表达自己。</p><p>我注意到的一些特点包括：</p><ul><li>跨平台支持</li><li>能够自由地写写画画</li><li>能够添加注释</li><li>能够删除注释</li><li>可以使用荧光笔高亮显示你的白板的部分区域</li><li>单独互动和移动创建/绘制的项目</li><li>按顺序添加多个页面，可以继续教学而不需要擦除</li><li>能够在页面间滚动浏览</li><li>绘制线条（从三种不同线宽中选择）</li><li>切换手写笔模式（如果你使用的是手写板或类似的东西）</li><li>轻松擦除在白板上创建的项目</li><li>可以从一组不同的背景中选择，包括把它变成黑板或带网格线的背景</li><li>各种必要的应用，包括计算器、地图、尺子等，都可以通过拖放使用</li><li>提供的一些形状，可以使绘图更容易</li><li>能够向你的白板添加音频/视频，并无缝播放，以获得更好的体验</li><li>虚拟激光笔</li><li>可放大和缩小</li><li>书写文字，调整大小，并克隆它</li><li>从白板中对屏幕进行截图</li><li>需要时可使用虚拟键盘</li></ul><p>在我简短的测试中，用户界面和可用的选项工作得非常好，没有任何故障。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/openboard-dock.png?resize=800%2C344&amp;ssl=1" alt=""></p><p>当然，你的体验将取决于设备的类型和你的设置。你可以用 Wacom 平板、双显示器设置，或者通过支持触摸的笔记本电脑使用投影仪来尝试。</p><h3 id="在-linux-中安装-openboard" tabindex="-1">在 Linux 中安装 OpenBoard <a class="header-anchor" href="#在-linux-中安装-openboard" aria-label="Permalink to “在 Linux 中安装 OpenBoard”">​</a></h3><p>更好的是，它可以在多个平台上使用，包括 Windows、macOS 和 Linux。</p>',22)),e("p",null,[t[2]||(t[2]=o("如果你使用的是 Ubuntu，你可以到官方网站下载 DEB 文件。另外对于其他 Linux 发行版，你可以选择通过 ",-1)),n(l,{href:"https://flathub.org/apps/details/ch.openboard.OpenBoard"},{default:p(()=>[...t[0]||(t[0]=[o("Flathub",-1)])]),_:1}),t[3]||(t[3]=o()),n(l,{href:"https://itsfoss.com/flatpak-guide/"},{default:p(()=>[...t[1]||(t[1]=[o("安装 Flatpak 软件包",-1)])]),_:1}),t[4]||(t[4]=o("。",-1))]),e("ul",null,[e("li",null,[n(l,{href:"https://www.openboard.ch/index.en.html"},{default:p(()=>[...t[5]||(t[5]=[o("OpenBoard",-1)])]),_:1})])]),t[22]||(t[22]=e("h3",{id:"结语",tabindex:"-1"},[o("结语 "),e("a",{class:"header-anchor",href:"#结语","aria-label":"Permalink to “结语”"},"​")],-1)),t[23]||(t[23]=e("p",null,"总的来说，我发现它在使用和导航方面毫不费力。你可以在多个页面之间快速切换，无缝擦除/添加项目，同时还可以在白板上添加丰富的元素。",-1)),t[24]||(t[24]=e("p",null,"通过虚拟激光笔以及一些应用，使得它适合在各种中小学和大学中使用而没有任何障碍。",-1)),t[25]||(t[25]=e("p",null,"我不知道它是否可以被称为谷歌课堂或 Miro 白板功能的替代品，但对于更简单的使用，OpenBoard 可以胜任。",-1)),t[26]||(t[26]=e("p",null,"如果你还没有试过，我建议你试一试。你知道有什么比这更好的东西吗？请在下面的评论中告诉我。",-1)),t[27]||(t[27]=e("hr",null,null,-1)),e("p",null,[t[7]||(t[7]=o("via: ",-1)),n(l,{href:"https://itsfoss.com/openboard/"},{default:p(()=>[...t[6]||(t[6]=[o("https://itsfoss.com/openboard/",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=o("作者：",-1)),n(l,{href:"https://itsfoss.com/author/ankush/"},{default:p(()=>[...t[8]||(t[8]=[o("Ankush Das",-1)])]),_:1}),t[13]||(t[13]=o(" 选题：",-1)),n(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[9]||(t[9]=[o("lujun9972",-1)])]),_:1}),t[14]||(t[14]=o(" 译者：",-1)),n(l,{href:"https://github.com/geekpi"},{default:p(()=>[...t[10]||(t[10]=[o("geekpi",-1)])]),_:1}),t[15]||(t[15]=o(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=o("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[16]||(t[16]=[o("LCTT",-1)])]),_:1}),t[19]||(t[19]=o(" 原创编译，",-1)),n(l,{href:"https://linux.cn/"},{default:p(()=>[...t[17]||(t[17]=[o("Linux中国",-1)])]),_:1}),t[20]||(t[20]=o(" 荣誉推出",-1))])])}const C=r(u,[["render",m]]);export{h as __pageData,C as default};
